// BoxdApiServer is the server API for BoxdApi service.
// All implementations must embed UnimplementedBoxdApiServer
// for forward compatibility.
type BoxdApiServer interface {
	CreateVm(context.Context, *CreateVmRequest) (*CreateVmResponse, error)
	DestroyVm(context.Context, *DestroyVmRequest) (*DestroyVmResponse, error)
	RenameVm(context.Context, *RenameVmRequest) (*RenameVmResponse, error)
	// Replaces a VM's whole network-tag set — not add/remove, the
	// caller sends the complete desired set. Networks drive east-west
	// reachability within the caller's org; see CreateVmRequest.networks.
	SetVmNetworks(context.Context, *SetVmNetworksRequest) (*SetVmNetworksResponse, error)
	// Replaces a VM's egress allowlist: hostnames / wildcards and
	// public IPv4 addresses / CIDRs the machine may reach. Empty = no
	// allowlist. `none` alone = an allowlist with nothing in it: the machine
	// reaches nothing (the hosts its network-scoped secrets are bound to
	// aside, as with any allowlist); next to other entries it is dropped.
	// Only reachable through the public API (no CLI, no in-VM route).
	SetVmEgressAllow(context.Context, *SetVmEgressAllowRequest) (*SetVmEgressAllowResponse, error)
	// Edits a machine's labels: user-set key=value metadata for
	// grouping and finding machines. Returns the labels after the edit.
	UpdateVmLabels(context.Context, *UpdateVmLabelsRequest) (*UpdateVmLabelsResponse, error)
	StartVm(context.Context, *StartVmRequest) (*StartVmResponse, error)
	StopVm(context.Context, *StopVmRequest) (*StopVmResponse, error)
	RebootVm(context.Context, *RebootVmRequest) (*RebootVmResponse, error)
	// NOT_FOUND for an id/name with no matching machine, INCLUDING a
	// destroyed one — a destroyed machine's id keeps resolving internally for
	// a while (until the archive sweeper reclaims the row), but this RPC
	// rejects it exactly like ListVms omits it and Exec refuses it, so a
	// caller polling GetVm to confirm teardown never sees a stale "running"
	// (or any other live-looking) status for a machine it already destroyed
	//.
	GetVm(context.Context, *GetVmRequest) (*GetVmResponse, error)
	ListVms(context.Context, *ListVmsRequest) (*ListVmsResponse, error)
	// A fresh, available auto-generated VM name — used by the interactive CLI to
	// pre-fill the "name" prompt for `machine new`.
	SuggestVmName(context.Context, *SuggestVmNameRequest) (*SuggestVmNameResponse, error)
	ExposePort(context.Context, *ExposePortRequest) (*ExposePortResponse, error)
	UnexposePort(context.Context, *UnexposePortRequest) (*UnexposePortResponse, error)
	ListExposedPorts(context.Context, *ListExposedPortsRequest) (*ListExposedPortsResponse, error)
	// Env vars & secrets (scoped to an org or, when org is empty, personal).
	SetVar(context.Context, *SetVarRequest) (*VarReply, error)
	ListVars(context.Context, *ListVarsRequest) (*VarListReply, error)
	RemoveVar(context.Context, *RemoveVarRequest) (*VarReply, error)
	SetSecretScope(context.Context, *SetSecretScopeRequest) (*VarReply, error)
	StreamLogs(*StreamLogsRequest, grpc.ServerStreamingServer[LogChunk]) error
	// Run a command (or interactive shell, with `tty`) inside the VM. The
	// first request chunk carries vm_id/command/tty; subsequent chunks carry
	// stdin bytes or a resize. The stream ends with a final ExecChunk carrying
	// `exit_code`.
	//
	// Cancelling the call — a client-side timeout expiring, or the caller
	// half-closing/cancelling the stream — does NOT just walk away from the
	// remote command: it kills it. The in-VM agent runs every exec'd command
	// in its own process group and, once it notices this RPC has
	// been torn down while the command is still running, sends SIGTERM to
	// that whole group, then SIGKILL after a short grace period if it hasn't
	// exited. Both SDKs' `timeout` / `stream.close()` (`close()`) go through
	// this same path.
	Exec(grpc.BidiStreamingServer[ExecChunk, ExecChunk]) error
	// Raw byte tunnel to the VM's desktop (xpra) socket, which is bound to the
	// guest's loopback and reachable ONLY through this authenticated RPC. The
	// first chunk carries vm_id (data ignored); every later chunk is opaque
	// xpra-protocol bytes, both directions. The proxy starts the in-VM
	// boxd-desktop unit on demand before splicing. Consumed by the console's
	// /desktop view via boxd-console's WebSocket bridge.
	DesktopTunnel(grpc.BidiStreamingServer[DesktopChunk, DesktopChunk]) error
	CreateNetwork(context.Context, *CreateNetworkRequest) (*CreateNetworkResponse, error)
	ListNetworks(context.Context, *ListNetworksRequest) (*ListNetworksResponse, error)
	// Per-VM custom domains (one domain -> one VM). AddCustomDomain creates a
	// `pending` row and a leader-gated control loop immediately starts
	// verifying DNS and issuing certs, then flips it `active`; `last_error`
	// carries the reason while pending. Callers are expected to have already
	// pointed DNS at the machine before calling this — checking too early
	// risks a public resolver negative-caching the apex before the records
	// exist. Caller must own (or be a member of the org of) the target VM.
	AddCustomDomain(context.Context, *AddCustomDomainRequest) (*AddCustomDomainResponse, error)
	ListCustomDomains(context.Context, *ListCustomDomainsRequest) (*ListCustomDomainsResponse, error)
	RemoveCustomDomain(context.Context, *RemoveCustomDomainRequest) (*RemoveCustomDomainResponse, error)
	// Per-org wildcard domain (one apex per org, e.g. preview.mysaas.com,
	// covering <vm>.preview.mysaas.com for every org-billed VM). Same
	// already-pointed-DNS expectation as AddCustomDomain, this time NS
	// delegation. Set/Clear require org admin; Get is readable by any org member.
	// An org has at most one domain in each region, set through that region's
	// API (`region` names it; "" is the region the endpoint serves), and the
	// domain is delegated to that region's nameservers (ns1 and ns2 of its zone).
	SetOrgDomain(context.Context, *SetOrgDomainRequest) (*SetOrgDomainResponse, error)
	GetOrgDomain(context.Context, *GetOrgDomainRequest) (*GetOrgDomainResponse, error)
	ClearOrgDomain(context.Context, *ClearOrgDomainRequest) (*ClearOrgDomainResponse, error)
	Whoami(context.Context, *WhoamiRequest) (*WhoamiResponse, error)
	CreateToken(context.Context, *CreateTokenRequest) (*CreateTokenResponse, error)
	ListTokens(context.Context, *ListTokensRequest) (*ListTokensResponse, error)
	RevokeToken(context.Context, *RevokeTokenRequest) (*RevokeTokenResponse, error)
	// Link an SSH public key to the caller's account so `ssh <vm>.boxd`
	// authenticates by that key's fingerprint. Idempotent for the caller.
	LinkSshKey(context.Context, *LinkSshKeyRequest) (*LinkSshKeyResponse, error)
	GetConfig(context.Context, *GetConfigRequest) (*GetConfigResponse, error)
	ForkVm(context.Context, *ForkVmRequest) (*ForkVmResponse, error)
	ListProxies(context.Context, *ListProxiesRequest) (*ListProxiesResponse, error)
	// The cluster's PROXY NODES — not to be confused with ListProxies above,
	// which returns a VM's HTTP port-forwards. Used by the client-utilities
	// daemon to open a DeviceBridge to every proxy: the device registry is
	// per-process and in-memory, so registering with only one proxy leaves the
	// device invisible to the others.
	ListProxyNodes(context.Context, *ListProxyNodesRequest) (*ListProxyNodesResponse, error)
	CreateProxy(context.Context, *CreateProxyRequest) (*CreateProxyResponse, error)
	DeleteProxy(context.Context, *DeleteProxyRequest) (*DeleteProxyResponse, error)
	SetProxyPort(context.Context, *SetProxyPortRequest) (*SetProxyPortResponse, error)
	UploadFile(context.Context, *UploadFileRequest) (*UploadFileResponse, error)
	// Streaming upload: lifts the 4 MiB single-message gRPC cap of UploadFile.
	// The first chunk carries vm_id/path/total_size; subsequent chunks carry
	// bytes only. Server side reads exactly total_size bytes via `head -c N`,
	// verifies the file size, and returns the confirmed byte count.
	UploadFileStream(grpc.ClientStreamingServer[UploadFileChunk, UploadFileResponse]) error
	DownloadFile(context.Context, *DownloadFileRequest) (*DownloadFileResponse, error)
	// Streaming download: the sibling of UploadFileStream, lifting the 4 MiB
	// single-message gRPC cap of DownloadFile. The first response chunk carries
	// `total_size`; every chunk (the first included) carries a slice of the
	// file's bytes in order. The client concatenates them and MUST verify the
	// received byte count against `total_size` — a short stream is an error,
	// not a truncated file.
	DownloadFileStream(*DownloadFileRequest, grpc.ServerStreamingServer[DownloadFileChunk]) error
	// Lists the immediate (non-recursive) contents of a directory inside the
	// guest — one level, not a recursive tree. Backs the console's file
	// browser and the Python/TypeScript SDKs' `machines.files` namespace; not
	// exposed by boxd-cli, whose users already have `machine exec`/`connect`
	// for this.
	ListDir(context.Context, *ListDirRequest) (*ListDirResponse, error)
	// Directory/file management for the console's file browser and the
	// Python/TypeScript SDKs — mirrors `mkdir`/`mv`/`rm -rf` inside the guest.
	// Not exposed by boxd-cli (same reasoning as ListDir).
	Mkdir(context.Context, *MkdirRequest) (*MkdirResponse, error)
	RenamePath(context.Context, *RenamePathRequest) (*RenamePathResponse, error)
	DeletePath(context.Context, *DeletePathRequest) (*DeletePathResponse, error)
	// Copy (mirrors `cp -r`) -- RenamePath already covers a guest-side Cut,
	// since a move is exactly what "cut then paste" means.
	CopyPath(context.Context, *CopyPathRequest) (*CopyPathResponse, error)
	// Filesystem: read, write, stat, list, mkdir, remove, rename and realpath
	// inside a machine, for programs that work with its files (the SDKs'
	// `machines.fs`). Each call runs as the machine's user, in the same
	// filesystem view `Exec` commands see, and wakes a sleeping machine first.
	//
	// Paths are raw bytes, so any filename works, including ones that are not
	// valid UTF-8. A relative path resolves from the user's home directory.
	//
	// Errors use the gRPC code that matches the failure (NOT_FOUND,
	// PERMISSION_DENIED, ALREADY_EXISTS, INVALID_ARGUMENT, FAILED_PRECONDITION)
	// and name the exact reason in the `x-boxd-error-reason` trailer:
	// `not_found`, `permission_denied`, `file_exists`, `is_a_directory`,
	// `not_a_directory`, `directory_not_empty`, `not_a_regular_file`,
	// `symlink_loop`, `name_too_long`, `invalid_path`, `no_space`,
	// `read_only`, `busy`, `cross_device`, `size_mismatch`, `io_error`, or
	// `agent_outdated` for a machine started before these calls existed
	// (rebooting it updates it).
	//
	// FsRead streams a file: the first chunk carries its entry, then data, and
	// the last chunk has `eof` set and the byte count sent. Only regular files
	// can be read; a FIFO or device is `not_a_regular_file`.
	FsRead(*FsReadRequest, grpc.ServerStreamingServer[FsReadChunk]) error
	// FsWrite replaces a file's contents from a stream. The first chunk names
	// the machine and path. Missing parent directories are created, a symlink
	// is written through to its target, and an existing file keeps its mode
	// and owner. The new contents appear all at once (written beside the file,
	// then renamed over it) unless that would change the file's identity: a
	// file with several hard links, one owned by another user, a mount point,
	// or one in a directory the user can't write to is overwritten in place.
	FsWrite(grpc.ClientStreamingServer[FsWriteChunk, FsWriteResponse]) error
	FsStat(context.Context, *FsStatRequest) (*FsStatResponse, error)
	// FsList streams a directory's entries, one level, in batches. There is no
	// cap on how many it returns.
	FsList(*FsListRequest, grpc.ServerStreamingServer[FsListChunk]) error
	// FsMkdir creates a directory and any missing parents. An existing
	// directory is not an error; a file in the way is `file_exists`.
	FsMkdir(context.Context, *FsMkdirRequest) (*FsMkdirResponse, error)
	// FsRemove removes a file or a symlink (never its target). A directory
	// needs `recursive`, and the root directory is refused.
	FsRemove(context.Context, *FsRemoveRequest) (*FsRemoveResponse, error)
	FsRename(context.Context, *FsRenameRequest) (*FsRenameResponse, error)
	// FsRealpath resolves symlinks and `.`/`..` like Python's
	// `os.path.realpath(path)`: missing components are kept as written, and a
	// symlink loop is `symlink_loop`.
	FsRealpath(context.Context, *FsRealpathRequest) (*FsRealpathResponse, error)
	SuspendVm(context.Context, *SuspendVmRequest) (*SuspendVmResponse, error)
	ResumeVm(context.Context, *ResumeVmRequest) (*ResumeVmResponse, error)
	HibernateVm(context.Context, *HibernateVmRequest) (*HibernateVmResponse, error)
	WakeVm(context.Context, *WakeVmRequest) (*WakeVmResponse, error)
	// Templates are managed by the platform and used only as the fast default
	// path of `new` when a prepped template matches the image + size — there is no
	// public API to create/list/delete templates or create a VM from a specific one.
	// Snapshots: user/org point-in-time VM captures (memory + disk), replicated
	// across a few workers and versioned (latest-only).
	CreateSnapshot(context.Context, *CreateSnapshotRequest) (*CreateSnapshotResponse, error)
	ListSnapshots(context.Context, *ListSnapshotsRequest) (*ListSnapshotsResponse, error)
	GetSnapshot(context.Context, *GetSnapshotRequest) (*GetSnapshotResponse, error)
	DeleteSnapshot(context.Context, *DeleteSnapshotRequest) (*DeleteSnapshotResponse, error)
	CreateVmFromSnapshot(context.Context, *CreateVmFromSnapshotRequest) (*CreateVmResponse, error)
	// Checkpoints: per-VM, worker-local full captures (state+memory+disk) with
	// warm restore in place. Same artifacts as a snapshot, but never replicated
	// and never an account-level image — they live and die with the VM.
	CreateCheckpoint(context.Context, *CreateCheckpointRequest) (*CreateCheckpointResponse, error)
	ListCheckpoints(context.Context, *ListCheckpointsRequest) (*ListCheckpointsResponse, error)
	DeleteCheckpoint(context.Context, *DeleteCheckpointRequest) (*DeleteCheckpointResponse, error)
	RestoreCheckpoint(context.Context, *RestoreCheckpointRequest) (*RestoreCheckpointResponse, error)
	SetAutoSuspendTimeout(context.Context, *SetAutoSuspendTimeoutRequest) (*SetAutoSuspendTimeoutResponse, error)
	SetAutoHibernateTimeout(context.Context, *SetAutoHibernateTimeoutRequest) (*SetAutoHibernateTimeoutResponse, error)
	SetBotProtection(context.Context, *SetBotProtectionRequest) (*SetBotProtectionResponse, error)
	SetIdleIgnoreOutbound(context.Context, *SetIdleIgnoreOutboundRequest) (*SetIdleIgnoreOutboundResponse, error)
	SetSsh(context.Context, *SetSshRequest) (*SetSshResponse, error)
	SetDeleteAfter(context.Context, *SetDeleteAfterRequest) (*SetDeleteAfterResponse, error)
	// Disks
	CreateDisk(context.Context, *CreateDiskRequest) (*CreateDiskResponse, error)
	ListDisks(context.Context, *ListDisksRequest) (*ListDisksResponse, error)
	AttachDisk(context.Context, *AttachDiskRequest) (*AttachDiskResponse, error)
	DetachDisk(context.Context, *DetachDiskRequest) (*DetachDiskResponse, error)
	DestroyDisk(context.Context, *DestroyDiskRequest) (*DestroyDiskResponse, error)
	// API Keys
	CreateApiKey(context.Context, *CreateApiKeyRequest) (*CreateApiKeyResponse, error)
	ListApiKeys(context.Context, *ListApiKeysRequest) (*ListApiKeysResponse, error)
	DeleteApiKey(context.Context, *DeleteApiKeyRequest) (*DeleteApiKeyResponse, error)
	// Billing — individual subscriptions. ListPlans is unauth-friendly
	// (returns the single self-serve plan), the rest require JWT.
	// RPC ChangeShape removed (shape retired, rc/0.2) — it only ever returned
	// UNIMPLEMENTED in prod. Do not reuse the method name with new semantics.
	ListPlans(context.Context, *ListPlansRequest) (*ListPlansResponse, error)
	GetBilling(context.Context, *GetBillingRequest) (*GetBillingResponse, error)
	CreateCheckoutSession(context.Context, *CreateCheckoutSessionRequest) (*CreateCheckoutSessionResponse, error)
	CreateBillingPortalSession(context.Context, *CreateBillingPortalSessionRequest) (*CreateBillingPortalSessionResponse, error)
	// Organizations (v2 org model). Owner-only visibility toggle: share your VM
	// with the whole org it belongs to, or make it private again. A VM never
	// moves between orgs (it's born in the owner's org).
	ShareVm(context.Context, *ShareVmRequest) (*ShareVmResponse, error)
	UnshareVm(context.Context, *UnshareVmRequest) (*UnshareVmResponse, error)
	// List the orgs the caller is a member of (backs the CLI/console org picker).
	ListOrgs(context.Context, *ListOrgsRequest) (*ListOrgsResponse, error)
	// The org's shared plan: aggregate quota + current usage. Any member may
	// view it (read-only; the platform sets the quota).
	GetOrgBilling(context.Context, *GetOrgBillingRequest) (*GetOrgBillingResponse, error)
	// Usage and cost: what each machine used and cost over a window,
	// and billing activity (what was actually charged). Org owners and admins
	// only; API keys fenced to the org work, tokens minted inside a VM don't.
	GetOrgUsage(context.Context, *GetOrgUsageRequest) (*GetOrgUsageResponse, error)
	GetVmUsage(context.Context, *GetVmUsageRequest) (*GetVmUsageResponse, error)
	ListBillingActivity(context.Context, *ListBillingActivityRequest) (*ListBillingActivityResponse, error)
	// Disaster recovery: scheduled VM disk backups to object storage. Off by default — SetBackupSchedule
	// is refused server-side if the cluster has no [backups] object store
	// configured.
	SetBackupSchedule(context.Context, *SetBackupScheduleRequest) (*SetBackupScheduleResponse, error)
	ClearBackupSchedule(context.Context, *ClearBackupScheduleRequest) (*ClearBackupScheduleResponse, error)
	GetBackupSchedule(context.Context, *GetBackupScheduleRequest) (*GetBackupScheduleResponse, error)
	ListBackups(context.Context, *ListBackupsRequest) (*ListBackupsResponse, error)
	// On-demand "back up now" — captures immediately, independent of
	// (and without disturbing) any schedule. Retention resolves from the VM's
	// schedule, else the org default, else the platform default.
	TriggerBackup(context.Context, *TriggerBackupRequest) (*TriggerBackupResponse, error)
	// Manual deletion of a single backup by id. Refused for a backup
	// still being captured or one a newer dedup pointer depends on.
	DeleteBackup(context.Context, *DeleteBackupRequest) (*DeleteBackupResponse, error)
	// Restore is IN-PLACE and DESTRUCTIVE (Q1: full disk rewrite, no
	// fork-from-backup) — callers must get explicit user confirmation first.
	RestoreBackup(context.Context, *RestoreBackupRequest) (*RestoreBackupResponse, error)
	// The org's default backup schedule for NEW VMs (existing VMs are
	// unchanged; a fork always copies its own source's schedule instead of
	// this default). Self-service: org admins set it themselves.
	// Set/Clear require org admin; Get is readable by any member — same shape
	// as SetOrgDomain/GetOrgDomain above.
	SetOrgBackupsDefault(context.Context, *SetOrgBackupsDefaultRequest) (*SetOrgBackupsDefaultResponse, error)
	GetOrgBackupsDefault(context.Context, *GetOrgBackupsDefaultRequest) (*GetOrgBackupsDefaultResponse, error)
	// The org's default machine SIZE: what a machine gets at CREATE
	// when the request names no size. Distinct from the quota: the quota stays
	// the operator-owned ceiling and the per-request maximum; this is the
	// org-admin-owned preference below it (clamped to the ceiling). Every
	// machine keeps the size it was created with, so changing this only
	// affects machines created afterwards.
	// Set/Clear require org admin; Get is readable by any member.
	SetOrgMachineDefaults(context.Context, *SetOrgMachineDefaultsRequest) (*SetOrgMachineDefaultsResponse, error)
	GetOrgMachineDefaults(context.Context, *GetOrgMachineDefaultsRequest) (*GetOrgMachineDefaultsResponse, error)
	// The org's default for idle.ignore-outbound: whether a NEW
	// machine in the org starts with its idle clock ignoring outbound traffic
	// when its create request does not say. An org without one follows the
	// platform's setting. Setting it also sets it on the existing machines and
	// snapshots the caller may manage, unless the Set asks for
	// `new_machines_only`; a fork or a restore keeps its source's
	// value either way.
	// Set/Clear require org admin; Get is readable by any member.
	SetOrgIdleIgnoreOutboundDefault(context.Context, *SetOrgIdleIgnoreOutboundDefaultRequest) (*SetOrgIdleIgnoreOutboundDefaultResponse, error)
	GetOrgIdleIgnoreOutboundDefault(context.Context, *GetOrgIdleIgnoreOutboundDefaultRequest) (*GetOrgIdleIgnoreOutboundDefaultResponse, error)
	// The org's default bot protection mode: what a NEW machine in
	// the org starts with. An org without one follows the cluster's setting
	// for new machines. Every machine keeps the mode it has, so changing this
	// only affects machines created afterwards; a fork or a restore keeps its
	// source's mode either way.
	// Set/Clear require org admin; Get is readable by any member.
	SetOrgBotProtectionDefault(context.Context, *SetOrgBotProtectionDefaultRequest) (*SetOrgBotProtectionDefaultResponse, error)
	GetOrgBotProtectionDefault(context.Context, *GetOrgBotProtectionDefaultRequest) (*GetOrgBotProtectionDefaultResponse, error)
	// The org's machine limit (how many machines it may have at once) and
	// asking for a higher one. Get is readable by any member, with a login or
	// an API key issued for the org. Request is the org owner's: with their
	// login, or an API key of theirs issued for the org; a token minted inside
	// a machine can't make one. One request may be open per org at a time; the
	// owner gets an email when the limit changes.
	GetOrgMachineLimit(context.Context, *GetOrgMachineLimitRequest) (*GetOrgMachineLimitResponse, error)
	RequestOrgMachineLimit(context.Context, *RequestOrgMachineLimitRequest) (*RequestOrgMachineLimitResponse, error)
	// The regions boxd runs in. Each has its own API endpoint and DNS zone,
	// and a machine, snapshot or disk lives in one of them. An org can use
	// its home region and the regions enabled for it; ListRegions says which,
	// for an org you belong to. An org admin can ask for another region with
	// RequestOrgRegion (with their login, or an API key of theirs issued for
	// the org; a token minted inside a machine can't); boxd enables it.
	ListRegions(context.Context, *ListRegionsRequest) (*ListRegionsResponse, error)
	RequestOrgRegion(context.Context, *RequestOrgRegionRequest) (*RequestOrgRegionResponse, error)
	// Where else a name is: the regions where your orgs have a machine, snapshot,
	// disk or template of that name, and close names (one or two letters off).
	// Answers "not found here" with where to look instead.
	FindElsewhere(context.Context, *FindElsewhereRequest) (*FindElsewhereResponse, error)
	// Org creation, roster, and membership (self-serve, same business rules as
	// the console). Any signed-in
	// user may create an org (becomes its owner+admin); invite/revoke/remove/
	// set-role require org admin.
	//
	// Credential fence: an API key or in-VM token only ever acts on the org it
	// is fenced to ("" resolves to it, any other org is refused); an in-VM
	// token can read a roster but never change one; an `org`-kind (userless)
	// credential has no org/team verbs at all. Creating an org, inviting an
	// admin, and promoting to admin need an interactive session — no ambient
	// credential may confer permanent standing.
	CreateOrg(context.Context, *CreateOrgRequest) (*CreateOrgResponse, error)
	RenameOrg(context.Context, *RenameOrgRequest) (*RenameOrgResponse, error)
	GetOrgMembers(context.Context, *GetOrgMembersRequest) (*GetOrgMembersResponse, error)
	// Best-effort emails the invite link (Resend, when configured) — the
	// returned accept_url always works even when email delivery fails or isn't
	// configured, same fallback the console relies on.
	InviteOrgMember(context.Context, *InviteOrgMemberRequest) (*InviteOrgMemberResponse, error)
	RevokeOrgInvite(context.Context, *RevokeOrgInviteRequest) (*RevokeOrgInviteResponse, error)
	// Refused for an org owner/admin (only the platform can remove those) or a member
	// who still owns VMs billed to this org — same guardrails as the console.
	RemoveOrgMember(context.Context, *RemoveOrgMemberRequest) (*RemoveOrgMemberResponse, error)
	// Promote a member to admin, or demote an admin back to member. Refused for
	// the owner (ownership is transferred by the platform) and for a target
	// that isn't a member. Demoting ANOTHER admin is owner-only (an admin may
	// only step down themselves) — otherwise any admin could demote a peer and
	// then RemoveOrgMember them, defeating that RPC's admin guard. Promoting to
	// admin needs an interactive session.
	SetOrgMemberRole(context.Context, *SetOrgMemberRoleRequest) (*SetOrgMemberRoleResponse, error)
	// Teams: org-scoped sub-grouping of members, each with an
	// optional default snapshot new team machines boot from. Creating a team
	// requires org admin; every other write requires team-admin (inherited by
	// every org admin, or held directly via a team_members.role='admin' row).
	ListTeams(context.Context, *ListTeamsRequest) (*ListTeamsResponse, error)
	GetTeam(context.Context, *GetTeamRequest) (*TeamInfo, error)
	CreateTeam(context.Context, *CreateTeamRequest) (*TeamInfo, error)
	RenameTeam(context.Context, *RenameTeamRequest) (*RenameTeamResponse, error)
	DestroyTeam(context.Context, *DestroyTeamRequest) (*DestroyTeamResponse, error)
	AddTeamMember(context.Context, *AddTeamMemberRequest) (*AddTeamMemberResponse, error)
	RemoveTeamMember(context.Context, *RemoveTeamMemberRequest) (*RemoveTeamMemberResponse, error)
	SetTeamMemberRole(context.Context, *SetTeamMemberRoleRequest) (*SetTeamMemberRoleResponse, error)
	// Must be a SHARED snapshot (not just accessible to the setter) — a private
	// default would silently work only for the admin who set it. Empty
	// snapshot_id clears the default.
	SetTeamDefaultSnapshot(context.Context, *SetTeamDefaultSnapshotRequest) (*SetTeamDefaultSnapshotResponse, error)
	// Resize a machine to another supported size class (1 vCPU · 4 GiB, 2 · 8,
	// or 4 · 16 - naming one dimension resolves to its class), within the org
	// quota ceiling (refused above it, never clamped). The new size persists immediately: a
	// running machine is rebooted to apply it (cold boot - in-memory state is
	// lost, disk is kept), a stopped machine picks it up at its next start.
	// Suspended and hibernated machines are refused (their saved memory state
	// was captured at the old size) - resume/wake first, then resize.
	ResizeVm(context.Context, *ResizeVmRequest) (*ResizeVmResponse, error)
	// Patch the spec of a machine created from one (GetVmResponse.spec) and
	// apply what changes. Allowed to whoever may edit the machine's labels,
	// networks and egress: its owner, or an org owner or admin on a shared
	// machine. See UpdateMachineSpecRequest.
	UpdateMachineSpec(context.Context, *UpdateMachineSpecRequest) (*UpdateMachineSpecResponse, error)
	mustEmbedUnimplementedBoxdApiServer()
}

